import{_ as s,c as a,o as t,ag as n}from"./chunks/framework.Bzez9NG9.js";const r="/space/img/1user.and.acc.png",c="/space/img/uaa1png.png",i="/space/img/uaa_2.png",y=JSON.parse('{"title":"Users and access","description":"Analyze and troubleshoot IBM Planning Analytics and TM1 user access, security groups, and effective permissions across cubes, dimensions, elements, and cells.","frontmatter":{"title":"Users and access","description":"Analyze and troubleshoot IBM Planning Analytics and TM1 user access, security groups, and effective permissions across cubes, dimensions, elements, and cells.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","user access","TM1 security","permissions","security groups","effective permissions","cube security","element security","cell security","ReadOnlyUser"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/users-and-access.md","filePath":"doc/planning-analytics/users-and-access.md"}'),o={name:"doc/planning-analytics/users-and-access.md"};function l(u,e,d,p,g,h){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="users-and-access" tabindex="-1">Users and access <a class="header-anchor" href="#users-and-access" aria-label="Permalink to &quot;Users and access&quot;">​</a></h1><p>The SPACE <strong>Users and access</strong> module helps you understand and troubleshoot IBM Planning Analytics user security. Select a TM1 user to see their security context and investigate why they can or cannot access particular cubes, dimensions, elements, or data.</p><p>This is useful when effective access is difficult to determine from security configuration alone—for example, when a user belongs to multiple groups or can open a cube but cannot see or update particular data.</p><p><strong>Users and access</strong> analyzes security in connected Planning Analytics environments. SPACE invitations, roles, and tokens are managed separately under <a href="./../configuration/access.html">Configuration → Access</a>.</p><h2 id="select-a-user" tabindex="-1">Select a user <a class="header-anchor" href="#select-a-user" aria-label="Permalink to &quot;Select a user&quot;">​</a></h2><p>Select the TM1 user you want to investigate and load their security context.</p><p><img src="'+r+'" alt="User picker" data-zoomable=""></p><p>SPACE then brings together the user&#39;s relevant security information so you can investigate their effective access from one place.</p><h2 id="security-groups-and-flags" tabindex="-1">Security groups and flags <a class="header-anchor" href="#security-groups-and-flags" aria-label="Permalink to &quot;Security groups and flags&quot;">​</a></h2><p>The user summary shows information including:</p><ul><li>security flags such as <strong>Admin</strong>, <strong>Enabled</strong>, and <strong>ReadOnlyUser</strong>;</li><li>the TM1 security groups to which the user belongs.</li></ul><p><img src="'+c+'" alt="User summary" data-zoomable=""></p><p>This provides the starting point for understanding which groups and security settings may be contributing to the user&#39;s access.</p><h2 id="cube-access" tabindex="-1">Cube access <a class="header-anchor" href="#cube-access" aria-label="Permalink to &quot;Cube access&quot;">​</a></h2><p>Select a cube to investigate the user&#39;s access to it.</p><p>SPACE shows which security groups grant access and the applicable access level, such as <strong>Read</strong>, <strong>Write</strong>, or <strong>Admin</strong>.</p><p><img src="'+i+'" alt="Cube selection" data-zoomable=""></p><p>From the cube, you can drill down into dimensions and elements to investigate more granular permissions and understand why a user can or cannot see particular data.</p><p>When available, use <strong>Cell data access</strong> at the bottom of the panel to investigate access at the cell level.</p><p>Together, these views help trace effective TM1 security from the user and their groups down to the model objects and data they are trying to access.</p>',20)]))}const f=s(o,[["render",l]]);export{y as __pageData,f as default};
